	res := db.Exec(decoded)
	if res.Error != nil {
		return "1 {" + res.Error.Error() + "}"
	}
	var cells []string
	for _, col := range res.Columns {
		cells = append(cells, tclRenderCell(col))
	}
	for _, row := range res.Rows {
		for _, val := range row {
			cells = append(cells, tclRenderCell(val))
		}
	}
	if len(cells) == 0 {
		return "0 {}"
	}
	return "0 {" + strings.Join(cells, " ") + "}"
